def status(self):
        observation = dict(reason='OBSERVATION_EXCEPTION', counts={})
        self._session_observation = observation
        if not self._origin_valid():
            observation['reason'] = 'ORIGIN_UNAPPROVED'
            return 'UNAVAILABLE'
        if self._visible("iframe[src*='challenges.cloudflare.com'], iframe[src*='hcaptcha.com'], iframe[src*='/recaptcha/']"):
            observation['reason'] = 'CHALLENGE_VISIBLE'
            return 'CHALLENGE_REQUIRED'
        if self._visible("input[type='password'], input[autocomplete='one-time-code']"):
            observation['reason'] = 'LOGIN_FIELDS_VISIBLE'
            return 'LOGIN_REQUIRED'
        contract, state = detect(self.page, self._visible, observation)
        if state == 'CONNECTED':
            if (self._visible("[role='dialog'], [role='alertdialog']")
                    or (contract == RAIL_INPUT_GROUP and self._current_secure_loader_blocking())):
                observation['reason'] = 'VISIBLE_BLOCKING_DIALOG'
                return 'UNAVAILABLE'
            if self._operation_contract is not None and contract != self._operation_contract:
                observation['reason'] = 'OPERATION_LAYOUT_CHANGED'
                return 'UNAVAILABLE'
            self._dom_contract = contract
        return state

